// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/version", wrapper.GetVersion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/bootstrap", wrapper.Bootstrap)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/session", wrapper.Logout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/session", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/session/reauthenticate", wrapper.Reauthenticate)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/account/password", wrapper.ChangePassword)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sessions/revoke-all", wrapper.RevokeSessions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/credentials", wrapper.ListCredentials)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/credentials", wrapper.CreateCredential)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/credentials/{id}", wrapper.RevokeCredential)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/capabilities", wrapper.GetCapabilities)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/modules", wrapper.GetModules)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/system/modules/{id}", wrapper.SetModule)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nginx/config-tree", wrapper.GetConfigTree)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/nginx/config-tree", wrapper.SaveConfigTree)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nginx/apply", wrapper.ApplyConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nginx/runtime", wrapper.GetNginxRuntime)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nginx/config-tree/preview", wrapper.PreviewConfigTree)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nginx/resources", wrapper.CreateResource)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/nginx/resources/{id}", wrapper.DeleteResource)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/nginx/resources/{id}", wrapper.PatchResource)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nginx/resources/{id}/copy", wrapper.CopyResource)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nginx/access-lists", wrapper.CreateAccessList)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/nginx/access-lists/{id}", wrapper.DeleteAccessList)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/nginx/access-lists/{id}", wrapper.UpdateAccessList)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/certificates", wrapper.ListCertificates)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/certificates", wrapper.ImportCertificate)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/certificates/{id}", wrapper.DeleteCertificate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/certificates/{id}", wrapper.GetCertificate)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/certificates/{id}/versions", wrapper.ReplaceCertificate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nginx/features", wrapper.GetNginxFeatures)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nginx/waf-policies", wrapper.CreateWAFPolicy)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/nginx/waf-policies/{id}", wrapper.DeleteWAFPolicy)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/nginx/waf-policies/{id}", wrapper.UpdateWAFPolicy)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nginx/revisions", wrapper.ListRevisions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nginx/revisions/{id}", wrapper.GetRevision)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tasks", wrapper.ListTasks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tasks/{id}", wrapper.GetTask)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/audit", wrapper.ListAudit)

	return m
}
